// Project-level, part-specific manufacturing operations. Coordinates in mm.
import {validateNotches} from './notch-engine.mjs';
const clone=v=>structuredClone(v);
export function basePart(p){if(!p.projectNotchBase)return p;const {projectNotchBase,projectNotchStatus,projectNotchWarnings,...rest}=p;return {...rest,notches:projectNotchBase,warnings:projectNotchWarnings??rest.warnings};}
export function notchFingerprint(p){p=basePart(p);return JSON.stringify([p.id,p.memberId,p.profile,p.material,p.frame,p.section,p.extent,p.endPlanes,p.drills,p.notches??[],p.warnings??[]]);}
export function notchOrigin(p){p=basePart(p);if(p.plate)throw Error('מגרעת בפרופיל בלבד');const f=p.frame;const dot=(a,b)=>a.reduce((v,n,i)=>v+n*b[i],0);const verts=p.section.outer.flatMap(([u,v])=>{const q=f.origin.map((a,i)=>a+u*f.x[i]+v*f.y[i]);let [lo,hi]=p.extent;for(let cut of p.endPlanes){const a=dot(cut.normal,f.z),b=dot(cut.normal,q.map((n,i)=>n-cut.origin[i]));const sign=cut.keep==='positive'?1:-1;if(Math.abs(a)<1e-9){if(b*sign<0)throw Error('מישור קצה לא נתמך');continue;}const z=-b/a;if(a*sign>0)lo=Math.max(lo,z);else hi=Math.min(hi,z);}if(lo>hi)throw Error('קצה גוף אינו תקין');return [[u,v,lo],[u,v,hi]]});return [0,1,2].map(i=>Math.min(...verts.map(v=>v[i])));}
export function partWithNotches(p,rows){p=basePart(p);if(!Array.isArray(rows)||p.plate)throw Error('מגרעת בפרופיל בלבד');const origin=notchOrigin(p);const ns=rows.map(r=>({id:r.id,type:'box',min:r.min.map((v,i)=>v+origin[i]),max:r.max.map((v,i)=>v+origin[i])}));const result={...p,notches:[...(p.notches??[]),...ns]};validateNotches(result);return result;}
export function notchRecord(p,rows){partWithNotches(p,rows);return {fingerprint:notchFingerprint(p),rows:clone(rows)};}
export function applyProjectNotches(snapshot,records={}){const errors=[...(snapshot.errors??[])],stale=[],parts=snapshot.parts.map(p=>{const r=records[p.id];if(!r)return p;try{if(r.fingerprint!==notchFingerprint(p))throw Error('גיאומטריית המקור השתנתה');return {...partWithNotches(p,r.rows),projectNotchBase:basePart(p).notches??[],projectNotchWarnings:basePart(p).warnings??[],projectNotchStatus:'current'};}catch(e){stale.push(p.id);errors.push({id:p.id,message:'מגרעת לא עדכנית: '+e.message});return {...p,projectNotchBase:basePart(p).notches??[],projectNotchWarnings:basePart(p).warnings??[],warnings:[...(p.warnings??[]),'מגרעת לא עדכנית - נדרש אישור מחדש'],projectNotchStatus:'stale'};}});for(const id of Object.keys(records))if(!snapshot.parts.some(p=>p.id===id)){stale.push(id);errors.push({id,message:'חלק עם מגרעת שמורה אינו קיים עוד'});}return {...snapshot,parts,errors,projectNotchStale:stale};}
// A real command on the existing project store, included in undo/redo and project serialization.
export function commitNotches(bridge,partId,record,expectedProjectId){const state=bridge.getState();if(state.project.id!==expectedProjectId)throw Error('הפרויקט השתנה');const ok=bridge.store.exec({label:'עדכון מגרעות ייצור',run:p=>{if(p.id!==expectedProjectId)throw Error('הפרויקט השתנה');const next=clone(p);next.fabricationNotches={...(next.fabricationNotches??{})};if(record?.rows?.length)next.fabricationNotches[partId]=clone(record);else delete next.fabricationNotches[partId];return next;}});if(!ok)throw Error('לא ניתן לשמור מגרעת בפרויקט (ייתכן שהמהדורה נעולה)');}
